from pathlib import Path
import json,hashlib,time
from branchwrite.browser_capture import BrowserConfig,PageInspection,render_snapshot
r=Path(__file__).resolve().parent;page=(r/'steered-index.html').read_bytes();checks=r/'steering-checks.py'
assert hashlib.sha256(page).hexdigest()=='ad0a00073d406faac7c658a1a1418ac30b0dd07f208e6deb0ef74649cc23abad'
rows=[]
for width,height in [(1280,800),(375,812)]:
 start=time.monotonic()
 result=render_snapshot(page,BrowserConfig(Path('/home/dflanag3/spatial-artifacts/branchwrite-mode-tool-20261019-v1/browser/chromium-1248/chrome-linux64/chrome'),width,height,inspection=PageInspection(checks,hashlib.sha256(checks.read_bytes()).hexdigest(),'custom')))
 image=r/('steered-'+str(width)+'.png');image.write_bytes(result.png)
 rows.append(dict(viewport=[width,height],status=result.inspection['status'],inspection=result.inspection,source_sha256=result.served_sha256,isolation=result.isolation,runtime_errors=result.runtime_errors,screenshot=str(image),elapsed_seconds=time.monotonic()-start))
 report=dict(status='PASS' if all(row['status']=='PASS' and not row['runtime_errors'] for row in rows) else 'FAIL',scope='Actual isolated Chromium: computed bold names; italic+underlined verbs; original greeting click; no mobile horizontal overflow. Page generated by installed dev40 terminal with active steering to Q4 HTTP server. No source modification.',source_sha256=hashlib.sha256(page).hexdigest(),observer_source_commit='9b5722f9',rows=rows)
 (r/'steering-browser-result.json').write_text(json.dumps(report,indent=2)+'\n')
 if report['status']!='PASS':break
print(json.dumps(dict(status=report['status'],viewports=[row['viewport'] for row in rows],inspections=[row['inspection'] for row in rows])))
